import{_ as i,l as n,o as e,c as s,v as o,p as l,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"安全经济学","description":"","frontmatter":{"title":"安全经济学","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/security-economics.md","filePath":"cs/security-economics.md","lastUpdated":1789023840000}'),p={name:"cs/security-economics.md"};function m(u,a,E,_,A,B){const t=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="安全经济学" tabindex="-1">安全经济学 <a class="header-anchor" href="#安全经济学" aria-label="Permalink to &quot;安全经济学&quot;">​</a></h1><div class="epigraph"><p>漏洞留下往往因为谁承担损失、谁承担修补成本不对齐。Anderson 问：激励，而不只是算法。补丁窗口、 visiblity、责任构成市场。</p><footer>—— Anderson, Why Information Security is Hard, ACSAC 2001；Anderson and Moore, The Economics of Information Security, Science 2006</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/tor-onion-routing">Tor</a>依赖志愿者中继。缺口是<strong>激励</strong>：谁付钱改进安全。本课经济学，接到金融栏的激励但不进 LOB。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>负外部性：软件厂商不承担全部事故。缺口是：责任、保险、信息披露、赏金。</p><h3 id="不是量化定价课" tabindex="-1">不是量化定价课 <a class="header-anchor" href="#不是量化定价课" aria-label="Permalink to &quot;不是量化定价课&quot;">​</a></h3><p>不把 CAPM 或限价簿搬进来。只谈安全主体的激励。</p><p><span class="marginnote">Anderson 2001/2006。可用安全下一课谈人。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照公地悲剧与赏金市场。下一课可用安全。</p>',12)),(e(),l(h,null,{default:r(()=>[c(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COST%5B%22%E4%BF%AE%E8%A1%A5%E6%88%90%E6%9C%AC%22%5D%20--%3E%20WHO%5B%22%E7%94%B1%E8%B0%81%E6%89%BF%E6%8B%85%22%5D%0A%20%20LOSS%5B%22%E4%BA%8B%E6%95%85%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20WHO2%5B%22%E7%94%B1%E8%B0%81%E6%89%BF%E6%8B%85%22%5D%0A%20%20WHO%20--%3E%20GAP%5B%22%E4%B8%8D%E5%AF%B9%E9%BD%90%E5%88%99%E6%B4%9E%E7%95%99%E4%B8%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>技术控制在激励错时会被关。可用安全下一课：用户也会关。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不进量化微观结构。可用安全下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Tor 靠激励维持中继；一般安全也靠激励。</li><li>损失与修补不对齐则洞留下。</li><li>赏金与责任是机制，不是道德说教。</li><li>下一课可用安全。</li><li>出处：Anderson, 2001；Anderson and Moore, 2006。</li></ul>',8))])}const b=i(p,[["render",m]]);export{T as __pageData,b as default};
